/**
 * KUSKAT - Catálogo Maestro de Cursos Técnicos Vocacionales Especializados
 * 10 Especialidades Técnicas - 4 Módulos de 10 Horas (40 Horas por Curso / 400 Horas Totales)
 * Fundamentado en la normativa salvadoreña: INCAF (D.L. 896), MTPS (D.L. 254 / D.E. 86),
 * SIGET, MINSAL (D.L. 955), MARN (D.L. 233), MAG (D.L. 315), ANDA y OSARTEC (D.L. 805).
 */

export type NormativeInstitution =
  | 'SIGET'
  | 'MTPS'
  | 'MINSAL'
  | 'MARN'
  | 'MAG'
  | 'ANDA'
  | 'OSARTEC'
  | 'INCAF';

export interface CourseQuizQuestion {
  id: string;
  question: string;
  statement?: string;
  options: { A: string; B: string; C: string; D: string };
  correctAnswer: 'A' | 'B' | 'C' | 'D';
  explanation: string;
  legalBasis?: string;
  legalOrTechnicalBasis?: string;
  technicalStandard?: string;
}

export interface WorkshopFormula {
  name: string;
  title?: string;
  expression: string;
  formula?: string;
  description: string;
  variables: { symbol: string; meaning: string; unit: string }[];
  practicalExample: string;
  example?: string;
  practicalApplication?: string;
}

export interface LegalCitation {
  institution: NormativeInstitution;
  decree: string;
  law?: string;
  article: string;
  articles?: string;
  summary: string;
  citationText?: string;
}

export interface SafetyProcedure {
  title: string;
  protocol: string;
  normativeRef: string;
  epp: string[];
}

export interface TechnicalCourseModule {
  number: number;
  title: string;
  hours: number;
  description: string;
  practicalSkills: string[];
  topics: {
    title: string;
    topic?: string;
    hours: number;
    content?: string;
    examples?: string[];
  }[];
  analyticalTopics?: { topic?: string; title?: string; hours: number }[];
  legalCitations: LegalCitation[];
  legalFramework?: LegalCitation[];
  workshopFormulas: WorkshopFormula[];
  safetyProtocols: string[];
  safetyProcedures?: SafetyProcedure[];
  quiz: CourseQuizQuestion[];
  quizQuestions?: CourseQuizQuestion[];
  examples?: string[];
}

export interface TechnicalCourse {
  id: string;
  title: string;
  category: string;
  icon: string;
  accentColor: string;
  badgeBg: string;
  badgeText: string;
  summary: string;
  targetAudience: string;
  totalHours: number;
  legalFramework: string[];
  normativeEntities?: NormativeInstitution[];
  modules: TechnicalCourseModule[];
  jobOpportunities: string[];
}

