for (const course of TECHNICAL_COURSES) {
  for (const mod of course.modules) {
    const primaryLaw = mod.legalCitations[0];
    const primaryFormula = mod.workshopFormulas[0];
    const primarySkill = mod.practicalSkills[0] || mod.title;
    const primarySafety = mod.safetyProtocols[0] || 'Uso obligatorio de Equipo de Protección Personal certificado.';

    const modExamples: string[] = [
      `Ejemplo Técnico 1 (Cálculo de taller e instrumentación en ${mod.title}): ${primaryFormula ? primaryFormula.practicalExample : `Aplicación directa de los parámetros nominales de ${course.title} midiendo magnitudes de entrada y salida con instrumentos calibrados.`}`,
      `Ejemplo Técnico 2 (Cumplimiento normativo e inspección en El Salvador): En una auditoría técnica bajo ${primaryLaw ? `${primaryLaw.institution} (${primaryLaw.decree}, ${primaryLaw.article})` : 'la normativa salvadoreña vigente'}, el especialista verifica documental y físicamente que "${primaryLaw ? primaryLaw.summary : mod.description}" se cumpla antes de autorizar la puesta en marcha.`,
      `Ejemplo Técnico 3 (Ejecución operativa de competencia laboral INCAF): Durante una orden de servicio real en ${course.category}, el técnico ejecuta la habilidad "${primarySkill}" siguiendo la secuencia de preparación de superficie, verificación dimensional, ajuste con herramienta dinamométrica y prueba funcional de recepción.`,
      `Ejemplo Técnico 4 (Protocolo de prevención de riesgos ocupacionales MTPS D.E. 86): Antes de intervenir el sistema en el Módulo ${mod.number} (${mod.title}), se aplica rigurosamente la directriz "${primarySafety}", delimitando el área de trabajo, verificando ausencia de energías residuales y registrando la lista de chequeo de seguridad.`,
      `Ejemplo Técnico 5 (Diagnóstico de fallas y control de calidad OSARTEC): Ante una desviación de operación detectada en un sistema de ${course.title}, se contrastan las lecturas reales contra la expresión "${primaryFormula ? primaryFormula.expression : 'parámetro nominal de diseño'}", corrigiendo la causa raíz y emitiendo la bitácora técnica de conformidad.`,
    ];

    mod.examples = modExamples;

    mod.topics = mod.topics.map((t, tIdx) => {
      const topicTitle = t.title || t.topic || `Tema ${tIdx + 1}`;
      const skillRef = mod.practicalSkills[tIdx % mod.practicalSkills.length] || primarySkill;
      const lawRef = mod.legalCitations[tIdx % mod.legalCitations.length] || primaryLaw;
      const safetyRef = mod.safetyProtocols[tIdx % mod.safetyProtocols.length] || primarySafety;
      const formulaRef = mod.workshopFormulas[tIdx % mod.workshopFormulas.length] || primaryFormula;

      const topicExamples: string[] = [
        `Ejemplo 1 (Aplicación directa en taller de "${topicTitle}"): En una práctica supervisada de ${course.title} (${t.hours} horas asignadas), el técnico implementa "${skillRef}" verificando las tolerancias de trabajo mediante la expresión técnica ${formulaRef ? formulaRef.expression : 'de referencia'} y documentando los valores iniciales y finales en la hoja de servicio.`,
        `Ejemplo 2 (Caso numérico y metrológico de "${topicTitle}"): ${formulaRef ? formulaRef.practicalExample : `Se miden tres puntos de control consecutivos en el banco de trabajo de ${topicTitle}, comprobando que la variación porcentual permanezca dentro del margen técnico permitido por el fabricante.`}`,
        `Ejemplo 3 (Inspección legal salvadoreña bajo ${lawRef ? lawRef.institution : 'INCAF/MTPS'}): Al ejecutar trabajos de "${topicTitle}" en instalaciones residenciales o industriales de El Salvador, se aplica el mandato de ${lawRef ? `${lawRef.decree} (${lawRef.article}): ${lawRef.summary}` : 'la normativa técnica nacional'} para garantizar cero infracciones regulatorias y total seguridad operativa.`,
        `Ejemplo 4 (Prevención de accidentes y control de riesgos en "${topicTitle}"): Durante las ${t.hours} horas de desarrollo práctico de este tema, se establece como barrera crítica de seguridad: "${safetyRef}". Si un operario detecta incumplimiento en el aislamiento o en el equipo de protección, detiene la maniobra y restablece las condiciones seguras antes de continuar.`,
        `Ejemplo 5 (Resolución de anomalías y entrega certificada de "${topicTitle}"): Cuando un cliente o supervisor reporta un fallo intermitente vinculado con "${topicTitle}", el especialista realiza pruebas de aislamiento, continuidad o hermeticidad paso a paso, reemplaza el elemento fuera de norma y valida el funcionamiento continuo bajo carga nominal.`,
      ];

      const topicContent = [
        `Fundamentación técnica e industrial del tema "${topicTitle}" (${t.hours} horas teóricas y prácticas dentro del Módulo ${mod.number}: ${mod.title} del curso ${course.title}): Este bloque formativo desarrolla las competencias analíticas, procedimentales y normativas exigidas por el Instituto Nacional de Capacitación y Formación (INCAF) y los estándares productivos de El Salvador.`,
        `En el ejercicio profesional de ${course.category}, el dominio de "${topicTitle}" requiere comprender la interacción física y operativa de los materiales, equipos e instrumentos de medición antes de ejecutar cualquier intervención en campo o taller. La descripción curricular del módulo establece que: ${mod.description}`,
        `Procedimiento técnico paso a paso y competencia práctica: El estándar de desempeño se articula directamente con la destreza laboral "${skillRef}". En la primera fase de ejecución, el profesional inspecciona las condiciones del entorno, selecciona las herramientas calibradas y verifica las especificaciones técnicas del fabricante. En la segunda fase, aplica el modelo cuantitativo de taller (${formulaRef ? `${formulaRef.name}: ${formulaRef.expression} — ${formulaRef.description}` : 'control dimensional y verificación de parámetros nominales'}), asegurando que cada magnitud medida se encuentre dentro de los rangos de operación segura.`,
        `Marco regulatorio salvadoreño e higiene ocupacional: Toda actividad relacionada con "${topicTitle}" se rige por las disposiciones de ${lawRef ? `${lawRef.institution} (${lawRef.decree}, ${lawRef.article}), que estipula: "${lawRef.summary}"` : 'la Ley General de Prevención de Riesgos en los Lugares de Trabajo (D.L. 254) y el Reglamento General D.E. 86 del MTPS'}. Asimismo, es de cumplimiento estricto el protocolo de seguridad: "${safetyRef}", junto con la correcta gestión de residuos y orden y limpieza del puesto de trabajo.`,
        `Casuística aplicada y 5 ejemplos concretos de taller:\n1. ${topicExamples[0]}\n2. ${topicExamples[1]}\n3. ${topicExamples[2]}\n4. ${topicExamples[3]}\n5. ${topicExamples[4]}`,
      ].join('\n\n');

      return {
        ...t,
        content: topicContent,
        examples: topicExamples,
      };
    });
  }
}

